UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 41, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 42, 7, NULL::text),(3, 170, 37, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 211, 1388, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='66018a78-3537-5622-ad4e-18ac78932a58' AND md5(a.contenido)='fc8b48e31b58034c94a13976da6f63d2' RETURNING a.id,md5(a.contenido) hash;